SELECT COUNT(*) AS distinct_pair_count
FROM (
  SELECT DISTINCT src_ip, dst_ip
  FROM network_flows
  WHERE source_dataset = 'ctu-7'
) t;

SELECT Template_Type_Description
FROM Ref_Template_Types
WHERE Template_Type_Code = 'AD';

SELECT Template_Type_Code, Template_Type_Description
FROM Ref_Template_Types
ORDER BY Template_Type_Code;

SELECT Name, SurfaceArea
FROM country
WHERE SurfaceArea > (
  SELECT MAX(SurfaceArea) FROM country WHERE Continent = 'Europe'
)
ORDER BY SurfaceArea DESC;

SELECT COUNT(*) AS missing_dst_port_count
FROM network_flows
WHERE source_dataset = 'ctu13_s7' AND dst_port IS NULL;
